using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using LXMF;
using NomadNet;

namespace NomadNet.Tests;

// Generated by executing unchanged primary NomadNet 1.4.4 f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
// GenerateNomadNetAttachmentPathVectors.py records actual Git-blob SHA256 and methods.
[Trait("Category", "Unit")]
public sealed class NomadNetAttachmentPathTests
{
    [Fact]
    [Trait("TestId", "T193")]
    public void ConfigurationMatchesExecutedPrimary()
    {
        using var stream = typeof(NomadNetAttachmentPathTests).Assembly.GetManifestResourceStream(
            "NomadNet.Tests.NomadNetAttachmentPathVectors.json")!;
        using var fixture = JsonDocument.Parse(stream);
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", fixture.RootElement.GetProperty("revision").GetString());
        Assert.Equal("c36ce4c537fe5af534910d1f5200d2a2ea5dd50f74bf9e4157222eff15614eb2",
            fixture.RootElement.GetProperty("sources").GetProperty("nomadnet/NomadNetworkApp.py").GetString());
        foreach (var item in fixture.RootElement.GetProperty("cases").EnumerateArray())
        {
            var input = item.GetProperty("input").GetString();
            var result = NomadNetConfigImport.Parse(input is null ? "" : "[client]\nattachment_save_path=\"" + input + "\"");
            Assert.Empty(result.UnsupportedKeys);
            Assert.Equal(item.GetProperty("observed").GetProperty("configured").GetString(),
                result.Settings.AttachmentSavePath?.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "$HOME")
                    .Replace('\\', '/'));
        }
        Assert.Null(new NomadNetSettings().AttachmentSavePath);
        Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse(
            "[client]\nattachment_save_path=~__dotreticulum_nonexistent_user__/export"));
        Assert.Equal(Path.GetFullPath("literal-$HOME"), NomadNetAttachmentExport.Destination(
            new() { AttachmentSavePath = "literal-$HOME" }, "unused"));
        Assert.Equal(Path.GetFullPath("fallback"), NomadNetAttachmentExport.Destination(
            new() { AttachmentSavePath = "", DownloadsPath = "fallback" }, "unused"));
        Assert.Equal(Path.GetFullPath(Path.Combine("profile", "downloads")),
            NomadNetAttachmentExport.Destination(new(), "profile"));
    }

    [Theory]
    [InlineData(" \t")]
    [InlineData("line\nbreak")]
    [InlineData("nul\0path")]
    [Trait("TestId", "T194")]
    public void InvalidConfigurationIsRejected(string path) =>
        Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse("[client]\nattachment_save_path='" + path + "'"));

    [Fact]
    [Trait("TestId", "T194")]
    public void OversizeConfigurationIsRejected() =>
        Assert.Throws<InvalidDataException>(() => NomadNetConfigImport.Parse("[client]\nattachment_save_path=" + new string('a', 2049)));
}

[Trait("Category", "Integration")]
public sealed class NomadNetAttachmentExportTests
{
    private static readonly string Id = new('a', 64);
    private static readonly byte[] PublicData = "public attachment observation"u8.ToArray();

    [Fact]
    [Trait("TestId", "T195")]
    public async Task ExportsMatchPrimaryNamesAndCollisionTiming()
    {
        var root = Root();
        try
        {
            var destination = Path.Combine(root, "explicit", "nested");
            var settings = NomadNetConfigImport.Parse("[client]\nattachment_save_path=\"" + destination + "\"").Settings;
            await settings.SaveAsync(root);
            Assert.False(Directory.Exists(destination));
            settings = await NomadNetSettings.OpenAsync(root);
            Assert.False(Directory.Exists(destination));
            using var stream = typeof(NomadNetAttachmentPathTests).Assembly.GetManifestResourceStream(
                "NomadNet.Tests.NomadNetAttachmentPathVectors.json")!;
            using var fixture = JsonDocument.Parse(stream);
            var observed = fixture.RootElement.GetProperty("cases").EnumerateArray()
                .Single(item => item.GetProperty("name").GetString() == "relative").GetProperty("observed");
            foreach (var item in observed.GetProperty("exports").EnumerateArray())
            {
                await Save(root, item.GetProperty("input").GetString()!);
                await File.WriteAllTextAsync(Path.Combine(root, "attachments", Id, "0.bin.name"),
                    item.GetProperty("input").GetString()!);
                var listed = await NomadNetAttachmentExport.ListAsync(root, Id);
                Assert.Single(listed);
                Assert.Equal(0, listed[0].Index);
                Assert.Equal(NomadNetAttachments.SafeName(item.GetProperty("input").GetString()), listed[0].Name);
                var output = await NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0);
                Assert.Equal(item.GetProperty("name").GetString(), Path.GetFileName(output));
                Assert.Equal(item.GetProperty("sha256").GetString(),
                    Convert.ToHexStringLower(SHA256.HashData(await File.ReadAllBytesAsync(output))));
                if (!OperatingSystem.IsWindows())
                    Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(output));
            }
            Assert.Empty(Directory.GetFiles(destination, "*.new"));
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    [Trait("TestId", "T196")]
    public async Task FailuresDoNotPublishPartialFilesAndHealthyExportRecovers()
    {
        var root = Root();
        try
        {
            var destination = Path.Combine(root, "exports");
            var settings = new NomadNetSettings { AttachmentSavePath = destination };
            await Save(root, "public.txt");
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => NomadNetAttachmentExport.SaveAsync(
                settings, root, Id, 0, new CancellationToken(true)));
            Assert.False(Directory.Exists(destination));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, "../bad", 0));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 64));
            var file = Path.Combine(root, "attachments", Id, "0.bin");
            await File.WriteAllBytesAsync(file, new byte[NomadNetAttachments.MaximumBytes + 1]);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            await File.WriteAllBytesAsync(file, "corrupt"u8.ToArray());
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            await Save(root, "public.txt");
            await File.WriteAllTextAsync(file + ".name", new string('x', 1025));
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            await Save(root, "public.txt");
            await File.WriteAllBytesAsync(file + ".name", [0xff]);
            await Assert.ThrowsAsync<DecoderFallbackException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            Assert.False(Directory.Exists(destination));
            await Save(root, "public.txt");
            await File.WriteAllTextAsync(destination, "public blocker");
            await Assert.ThrowsAsync<IOException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            File.Delete(destination);
            Directory.CreateDirectory(destination);
            Directory.CreateDirectory(Path.Combine(destination, "public.txt"));
            var output = await NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0);
            Assert.Equal("public_1.txt", Path.GetFileName(output));
            Assert.Equal(PublicData, await File.ReadAllBytesAsync(output));
            Assert.Empty(Directory.GetFiles(destination, "*.new"));
        }
        finally { Directory.Delete(root, true); }
    }

    [Fact]
    [Trait("TestId", "T197")]
    public async Task ConcurrentCollisionsAreBoundedAndNeverOverwrite()
    {
        var root = Root();
        try
        {
            var destination = Path.Combine(root, "exports");
            var settings = new NomadNetSettings { AttachmentSavePath = destination };
            await Save(root, "public.txt");
            var outputs = await Task.WhenAll(Enumerable.Range(0, 8).Select(_ =>
                NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0)));
            Assert.Equal(8, outputs.Distinct().Count());
            for (var index = 0; index <= NomadNetAttachmentExport.MaximumCollisions; index++)
                await File.WriteAllTextAsync(Path.Combine(destination, index == 0 ? "public.txt" : $"public_{index}.txt"), "public existing");
            await Assert.ThrowsAsync<IOException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            Assert.Empty(Directory.GetFiles(destination, "*.new"));
            Assert.Equal("public existing", await File.ReadAllTextAsync(Path.Combine(destination, "public.txt")));
            File.Delete(Path.Combine(destination, "public_42.txt"));
            Assert.EndsWith("public_42.txt", await NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
        }
        finally { Directory.Delete(root, true); }
    }

    [SupportedUnixAttachmentFact]
    [Trait("TestId", "T198")]
    public async Task RejectsDestinationAndNameLinksAndRecovers()
    {
        var root = Root();
        try
        {
            await Save(root, "public.txt");
            var destination = Path.Combine(root, "exports");
            var outside = Path.Combine(root, "outside");
            Directory.CreateDirectory(outside);
            Directory.CreateSymbolicLink(destination, outside);
            await Assert.ThrowsAsync<InvalidDataException>(() => NomadNetAttachmentExport.SaveAsync(
                new() { AttachmentSavePath = destination }, root, Id, 0));
            Assert.Empty(Directory.GetFiles(outside));
            Directory.Delete(destination);
            var name = Path.Combine(root, "attachments", Id, "0.bin.name");
            File.Delete(name);
            File.CreateSymbolicLink(name, Path.Combine(root, "missing"));
            await Assert.ThrowsAsync<IOException>(() => NomadNetAttachmentExport.SaveAsync(
                new() { AttachmentSavePath = destination }, root, Id, 0));
            File.Delete(name);
            await Save(root, "public.txt");
            Assert.True(File.Exists(await NomadNetAttachmentExport.SaveAsync(
                new() { AttachmentSavePath = destination }, root, Id, 0)));
        }
        finally { Directory.Delete(root, true); }
    }

    [LinuxAttachmentFact]
    [Trait("TestId", "T198")]
    public async Task DeniedDirectoryAndSpecialFilesFailWithoutBlockingAndRecover()
    {
        if (!OperatingSystem.IsLinux()) throw new PlatformNotSupportedException("Linux-only test was incorrectly selected.");
        var root = Root();
        var destination = Path.Combine(root, "exports");
        try
        {
            await Save(root, "public.txt");
            Directory.CreateDirectory(destination);
            File.SetUnixFileMode(destination, UnixFileMode.UserRead | UnixFileMode.UserExecute);
            var settings = new NomadNetSettings { AttachmentSavePath = destination };
            await Assert.ThrowsAsync<UnauthorizedAccessException>(() =>
                NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0));
            Assert.Empty(Directory.GetFiles(destination));
            File.SetUnixFileMode(destination, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
            var file = Path.Combine(root, "attachments", Id, "0.bin");
            File.Delete(file);
            var info = new System.Diagnostics.ProcessStartInfo("mkfifo") { UseShellExecute = false };
            info.ArgumentList.Add(file);
            using (var process = System.Diagnostics.Process.Start(info)!)
            {
                await process.WaitForExitAsync();
                Assert.Equal(0, process.ExitCode);
            }
            await Assert.ThrowsAsync<IOException>(() => NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0)
                .WaitAsync(TimeSpan.FromSeconds(5)));
            File.Delete(file);
            await Save(root, "public.txt");
            Assert.True(File.Exists(await NomadNetAttachmentExport.SaveAsync(settings, root, Id, 0)));
        }
        finally
        {
            if (Directory.Exists(destination))
                File.SetUnixFileMode(destination, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
            Directory.Delete(root, true);
        }
    }

    private static string Root()
    {
        var root = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomad-attachment-" + Guid.NewGuid().ToString("N")));
        Directory.CreateDirectory(root);
        return root;
    }

    private static Task Save(string root, string name) => NomadNetAttachments.SaveAsync(root, Id,
        new() { [LxmField.FileAttachments] = new object?[] { new object?[] { name, PublicData } } });

    private sealed class SupportedUnixAttachmentFactAttribute : FactAttribute
    {
        public SupportedUnixAttachmentFactAttribute()
        {
            if (!OperatingSystem.IsLinux() && !(OperatingSystem.IsMacOS() &&
                System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture == System.Runtime.InteropServices.Architecture.Arm64))
                Skip = "Symlink export tests require Linux or macOS ARM64.";
        }
    }

    private sealed class LinuxAttachmentFactAttribute : FactAttribute
    {
        public LinuxAttachmentFactAttribute()
        {
            if (!OperatingSystem.IsLinux())
                Skip = "Unix symlink creation/permissions require Linux; Windows requires additional privileges.";
        }
    }
}
